B.al9=s(["Sulh tek tarafl\u0131 bir i\u015flemdir.","Sulh iki tarafl\u0131 (kar\u015f\u0131l\u0131kl\u0131) bir i\u015flemdir; taraflar\u0131n anla\u015fmas\u0131yla kurulur.","Sulh yaln\u0131zca istinaf a\u015famas\u0131nda yap\u0131labilir.","Sulh hi\xe7bir zaman kesin h\xfck\xfcm do\u011furmaz."],t.s)
B.aue=new A.bv("taraf_07",B.eY,"Sulhun feragat ve kabulden ayr\u0131lan en belirgin \xf6zelli\u011fi nedir?",B.al9,1,"Feragat ve kabul tek tarafl\u0131 i\u015flemlerken sulh, taraflar\u0131n kar\u015f\u0131l\u0131kl\u0131 anla\u015fmas\u0131na dayanan iki tarafl\u0131 bir i\u015flemdir (HMK m. 313 vd.). Yarg\u0131lama giderleri kural olarak taraflar\u0131n anla\u015fmas\u0131na g\xf6re; anla\u015fma yoksa e\u015fit olarak payla\u015ft\u0131r\u0131l\u0131r.")
B.WP=new A.h(1,1,0.45098039215686275,0.5333333333333333,B.d)
B.io=new A.qf("Alternatif Uyu\u015fmazl\u0131k \xc7\xf6z\xfcmleri",B.WP,4,"arabuluculuk")
B.afG=s(["Tamamen ihtiyaridir, hi\xe7bir zorunluluk yoktur.","Arabulucuya ba\u015fvurulmu\u015f olmas\u0131 bir dava \u015fart\u0131d\u0131r.","Yaln\u0131zca taraflar isterse uygulan\u0131r ve dava a\xe7maya engel de\u011fildir.","Sadece toplu i\u015f uyu\u015fmazl\u0131klar\u0131nda zorunludur."],t.s)
B.atG=new A.bv("arabulucu_01",B.io,"\u0130\u015f\xe7i-i\u015fveren aras\u0131ndaki kanuna/s\xf6zle\u015fmeye dayanan i\u015f\xe7ilik alaca\u011f\u0131 ve i\u015fe iade davalar\u0131nda arabuluculu\u011fun rol\xfc nedir?",B.afG,1,"7036 say\u0131l\u0131 \u0130\u015f Mahkemeleri Kanunu m. 3: Kanuna, bireysel veya toplu i\u015f s\xf6zle\u015fmesine dayanan i\u015f\xe7i/i\u015fveren alaca\u011f\u0131, tazminat\u0131 ve i\u015fe iade taleplerinde arabulucuya ba\u015fvurulmu\u015f olmas\u0131 dava \u015fart\u0131d\u0131r.")
B.aez=s(["T\xfcm ticari davalar\u0131 istisnas\u0131z kapsar.","Konusu bir miktar paran\u0131n \xf6denmesi olan alacak ve tazminat taleplerini kapsar.","Yaln\u0131zca \u015firketler hukukundan do\u011fan davalar\u0131 kapsar.","Yaln\u0131zca kambiyo senetlerine ili\u015fkin davalar\u0131 kapsar."],t.s)
B.atS=new A.bv("arabulucu_02",B.io,"Ticari davalarda dava \u015fart\u0131 olan arabuluculuk hangi t\xfcr talepleri kapsar?",B.aez,1,"TTK m. 5/A: Konusu bir miktar paran\u0131n \xf6denmesi olan alacak ve tazminat talepleri hakk\u0131nda ticari davalarda, dava a\xe7\u0131lmadan \xf6nce arabulucuya ba\u015fvurulmu\u015f olmas\u0131 dava \u015fart\u0131d\u0131r.")
B.akZ=s(["Do\u011frudan davay\u0131 esastan reddeder.","Davac\u0131ya, son tutana\u011f\u0131n bir haftal\u0131k kesin s\xfcre i\xe7inde sunulmas\u0131 i\xe7in ihtarda bulunur; sunulmazsa dava usulden reddedilir.","Tutana\u011f\u0131 resen arabuluculuk b\xfcrosundan ister.","Davay\u0131 hi\xe7bir uyar\u0131 yapmadan g\xf6revsizlikle reddeder."],t.s)
B.atX=new A.bv("arabulucu_04",B.io,"Arabuluculuk dava \u015fart\u0131 olan bir davada, anla\u015fmaya var\u0131lamad\u0131\u011f\u0131na ili\u015fkin son tutanak dava dilek\xe7esine eklenmemi\u015fse mahkeme \xf6nce ne yapar?",B.akZ,1,"7036 m. 3/2: Arabulucuya ba\u015fvurulmu\u015f ancak son tutanak eklenmemi\u015fse, mahkeme davac\u0131ya bir haftal\u0131k kesin s\xfcre verir; bu s\xfcre i\xe7inde sunulmazsa dava dilek\xe7esi kar\u015f\u0131 tarafa tebli\u011fe \xe7\u0131kar\u0131lmadan dava usulden reddedilir. (Hi\xe7 ba\u015fvurulmam\u0131\u015fsa s\xfcre verilmeden do\u011frudan reddedilir.)")
B.amp=s(["K\u0131dem tazminat\u0131 talebi","Fazla mesai \xfccreti alaca\u011f\u0131","\u0130\u015f kazas\u0131 veya meslek hastal\u0131\u011f\u0131ndan kaynaklanan maddi-manevi tazminat davalar\u0131","\u0130hbar tazminat\u0131 talebi"],t.s)
B.atP=new A.bv("arabulucu_05",B.io,"A\u015fa\u011f\u0131dakilerden hangisi i\u015f hukukunda dava \u015fart\u0131 arabuluculu\u011fun kapsam\u0131 DI\u015eINDADIR?",B.amp,2,"7036 m. 3: \u0130\u015f kazas\u0131 veya meslek hastal\u0131\u011f\u0131ndan kaynaklanan maddi-manevi tazminat davalar\u0131 ile bunlarla ilgili tespit, itiraz ve r\xfccu davalar\u0131 dava \u015fart\u0131 arabuluculu\u011fun kapsam\u0131 d\u0131\u015f\u0131ndad\u0131r.")
B.ajK=s(["\xdc\xe7 hafta i\xe7inde; zorunlu h\xe2llerde en fazla bir hafta uzat\u0131labilir.","\u0130ki ay i\xe7inde; uzatma m\xfcmk\xfcn de\u011fildir.","Bir y\u0131l i\xe7inde.","S\xfcre \xf6ng\xf6r\xfclmemi\u015ftir."],t.s)
B.aub=new A.bv("arabulucu_06",B.io,"Dava \u015fart\u0131 arabuluculukta arabulucu, ba\u015fvuru tarihinden itibaren s\xfcreci kural olarak ne kadar s\xfcrede tamamlamal\u0131d\u0131r?",B.ajK,0,"\u0130\u015f ve ticari uyu\u015fmazl\u0131klarda arabulucu, g\xf6revlendirildi\u011fi tarihten itibaren s\xfcreci \xfc\xe7 hafta i\xe7inde sonu\xe7land\u0131r\u0131r; bu s\xfcre zorunlu h\xe2llerde arabulucu taraf\u0131ndan en fazla bir hafta uzat\u0131labilir.")
B.a8V=s(["Tan\u0131k","Senet","Yemin","Bilirki\u015fi"],t.s)
B.atV=new A.bv("ispat_11",B.dw,"Hukuki i\u015flemlerin miktar veya de\u011feri kanunda \xf6ng\xf6r\xfclen s\u0131n\u0131r\u0131 ge\xe7ti\u011fi takdirde kural olarak hangi delille ispat edilmesi zorunludur?",B.a8V,1,"HMK m. 200 uyar\u0131nca, bir hakk\u0131n do\u011fumu, d\xfc\u015f\xfcr\xfclmesi, devri, de\u011fi\u015ftirilmesi, yenilenmesi, ertelenmesi, ikrar\u0131 ve itfas\u0131 amac\u0131yla yap\u0131lan hukuki i\u015flemlerin, yap\u0131ld\u0131klar\u0131 zamanki miktar veya de\u011ferleri kanunda \xf6ng\xf6r\xfclen s\u0131n\u0131r\u0131 ge\xe7ti\u011fi takdirde kural olarak senetle ispatlanmas\u0131 zorunludur.")
B.a86=s(["Karde\u015fler aras\u0131ndaki hukuki i\u015flemler","E\u015fler aras\u0131ndaki hukuki i\u015flemler","Ortaklar aras\u0131ndaki ticari i\u015flemler","Altsoy ile \xfcstsoy aras\u0131ndaki hukuki i\u015flemler"],t.s)
B.aud=new A.bv("ispat_12",B.dw,"A\u015fa\u011f\u0131dakilerden hangisi, senetle ispat zorunlulu\u011fu olan bir hukuki i\u015flemin miktar ne olursa olsun tan\u0131kla ispat edilebilece\u011fi istisnai hallerden (delil ba\u015flang\u0131c\u0131 aranmaks\u0131z\u0131n) biri de\u011fildir?",B.a86,2,"HMK m. 203 uyar\u0131nca altsoy-\xfcstsoy, karde\u015fler ve e\u015fler aras\u0131ndaki i\u015flemlerde miktar ne olursa olsun tan\u0131k dinlenebilir. Ortaklar aras\u0131ndaki i\u015flemler kural olarak bu istisnaya dahil edilmemi\u015ftir.")
